UPDATE analysis_intent_rule
SET intent_code = #{intentCode}, intent_name = #{intentName}, keywords = #{keywords},
    priority = #{priority}, status = #{status}
WHERE id = #{id}

UPDATE analysis_plan_config
SET intent_code = #{intentCode}, is_gov = #{isGov}, table_name = #{tableName},
    metrics = #{metrics}, dimensions = #{dimensions}, chart_type = #{chartType},
    time_range = #{timeRange}, sql_template = #{sqlTemplate}, status = #{status}, sort = #{sort}
WHERE id = #{id}
